def sort012_sort(a: list[int]) -> list[int]:
    a.sort()
    return a

def sort012_count(a: list[int]) -> list[int]:
    c = [0, 0, 0]
    for x in a:
        c[x] += 1
    i = 0
    for v in range(3):
        for _ in range(c[v]):
            a[i] = v
            i += 1
    return a

def sort012(a: list[int]) -> list[int]:
    low = mid = 0
    high = len(a) - 1
    while mid <= high:
        if a[mid] == 0:
            a[low], a[mid] = a[mid], a[low]
            low += 1
            mid += 1
        elif a[mid] == 1:
            mid += 1
        else:
            a[mid], a[high] = a[high], a[mid]
            high -= 1
    return a
